
-- INITIALIZE SCHEMA

DROP TABLE IF EXISTS veg_foods CASCADE;
CREATE TABLE veg_foods (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    calories INTEGER NOT NULL,
    protein DECIMAL(5,1) NOT NULL,
    carbs DECIMAL(5,1) NOT NULL,
    fat DECIMAL(5,1) NOT NULL,
    serving_size VARCHAR(50) NOT NULL
);

DROP TABLE IF EXISTS non_veg_foods CASCADE;
CREATE TABLE non_veg_foods (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    calories INTEGER NOT NULL,
    protein DECIMAL(5,1) NOT NULL,
    carbs DECIMAL(5,1) NOT NULL,
    fat DECIMAL(5,1) NOT NULL,
    serving_size VARCHAR(50) NOT NULL
);

DROP TABLE IF EXISTS vegan_foods CASCADE;
CREATE TABLE vegan_foods (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    calories INTEGER NOT NULL,
    protein DECIMAL(5,1) NOT NULL,
    carbs DECIMAL(5,1) NOT NULL,
    fat DECIMAL(5,1) NOT NULL,
    serving_size VARCHAR(50) NOT NULL
);

DROP TABLE IF EXISTS keto_foods CASCADE;
CREATE TABLE keto_foods (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    calories INTEGER NOT NULL,
    protein DECIMAL(5,1) NOT NULL,
    carbs DECIMAL(5,1) NOT NULL,
    fat DECIMAL(5,1) NOT NULL,
    serving_size VARCHAR(50) NOT NULL
);

DROP TABLE IF EXISTS exercises CASCADE;
CREATE TABLE exercises (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    category VARCHAR(50) NOT NULL,
    muscle_group VARCHAR(100) NOT NULL,
    description TEXT,
    difficulty VARCHAR(50)
);

